// Source: create-order-flow.ts
// Example wallet values. Use the connected account and active chain from your host.
// Refresh these values when the wallet account or network changes.
const account: Address = "0x1111111111111111111111111111111111111111";
const chainId = 137;
// Use the connected EIP-1193 provider from your host wallet integration.
const walletProvider = (window as unknown as {
    ethereum: Parameters<typeof custom>[0];
}).ethereum;
const publicClient = createPublicClient({ transport: custom(walletProvider) });
const walletClient = createWalletClient({ account, transport: custom(walletProvider) });
const wrappedNativeAbi = parseAbi(["function deposit() payable"]);
export async function submitOrdersSinkOrder({ orderInput, wTokenAddress, }: {
    // Derived swap data owned by the host's form and state layer.
    orderInput: OrderInput;
    // Wrapped native token for the active chain, supplied by the host.
    wTokenAddress: Address;
}): Promise<OrderResponse> {
    // 1. Fetch the trusted default template for this partner and active chain.
    const permitData = await fetchDefaultPermitData("external", chainId);
    // 2. Prepare the complete source amount before asking for a signature.
    // Allowance belongs to RePermit, not to order.spender (the reactor).
    const spender = permitData.domain.verifyingContract;
    const inputTokenAddress = orderInput.sourceIsNative ? wTokenAddress : orderInput.inputToken.address;
    // Reject invalid amounts and strategy fields before any wallet transaction.
    validateOrderInput(orderInput, inputTokenAddress);
    const requiredAmount = BigInt(orderInput.totalInputAmount);
    let allowance = await publicClient.readContract({
        address: inputTokenAddress,
        abi: erc20Abi,
        functionName: "allowance",
        args: [account, spender],
    });
    if (orderInput.sourceIsNative) {
        // Wrap the complete amount, then use WToken everywhere in the signed order.
        const wrapHash = await walletClient.writeContract({
            address: wTokenAddress,
            abi: wrappedNativeAbi,
            functionName: "deposit",
            value: requiredAmount,
            account,
            chain: walletClient.chain,
        });
        const wrapReceipt = await publicClient.waitForTransactionReceipt({ hash: wrapHash });
        if (wrapReceipt.status !== "success")
            throw new Error("Native token wrap reverted");
    }
    if (allowance < requiredAmount) {
        // This direct-integration reference grants only the complete order amount.
        // A maximum allowance must be an explicit host security decision.
        const approveHash = await walletClient.writeContract({
            address: inputTokenAddress,
            abi: erc20Abi,
            functionName: "approve",
            args: [spender, requiredAmount],
            account,
            chain: walletClient.chain,
        });
        const approveReceipt = await publicClient.waitForTransactionReceipt({ hash: approveHash });
        if (approveReceipt.status !== "success")
            throw new Error("Token approval reverted");
        allowance = await publicClient.readContract({
            address: inputTokenAddress,
            abi: erc20Abi,
            functionName: "allowance",
            args: [account, spender],
        });
    }
    if (allowance < requiredAmount) {
        throw new Error("Confirmed approval is still insufficient");
    }
    // 3. Build and sign using the same permit data fetched above.
    const { order, signature } = await signOrder({
        orderInput,
        permitData,
        inputTokenAddress,
    });
    return submitOrder(order, signature);
}
async function submitOrder(order: PermitOrder, signature: Signature): Promise<OrderResponse> {
    const body: SignedOrder = { signature, order, status: "pending" };
    const response = await fetch("https://order-sink-v2.orbs.network/orders/new", {
        method: "POST",
        headers: {
            Accept: "application/json",
            "Content-Type": "application/json",
        },
        body: JSON.stringify(body),
    });
    const result = (await response.json().catch(() => ({}))) as CreateOrderResponse;
    if (!response.ok || !result.success) {
        const message = "message" in result ? result.message : undefined;
        throw new Error(message ?? response.statusText ?? "Order creation failed");
    }
    return result.signedOrder;
}
/*
Create order flow

1. Fetch and validate the default permit template for the partner and active chain.
2. Validate amounts and strategy fields, then check allowance, wrap native input when needed, and approve RePermit when
   allowance does not cover the complete order amount.
3. Pass the fetched permit data, derived values, and resolved input token
   to signOrder(). It builds and signs using that same template.
4. Submit the exact signed order and require HTTP and API success, then keep the returned signedOrder
   for progress, history, fills, and cancellation.

Use the connected account, chain, and wallet provider from the host for the
setup above. Recreate the clients when the wallet connection changes.
The flow itself stays framework-neutral.
*/
async function signOrder({ orderInput, permitData, inputTokenAddress, }: {
    orderInput: OrderInput;
    permitData: PermitData;
    inputTokenAddress: Address;
}): Promise<{
    order: PermitOrder;
    signature: Signature;
}> {
    const { order } = buildOrderFromDerivedValues({
        orderInput,
        permitData,
        inputTokenAddress,
    });
    const signTypedDataArgs = {
        account,
        domain: permitData.domain,
        message: order,
        primaryType: permitData.primaryType,
        types: permitData.types,
    } as const;
    // Keep the complete EIP-712 hex signature returned by the wallet.
    const signature = await walletClient.signTypedData(signTypedDataArgs);
    // Preserve the exact object that was signed for POST /orders/new.
    return { signature, order };
}
function buildOrderFromDerivedValues({ orderInput, permitData, inputTokenAddress, }: {
    // Derived swap data owned by the host's form and state layer.
    orderInput: OrderInput;
    // Resolved ERC-20 input address; use the wrapped token for native input.
    inputTokenAddress: Address;
    // Fresh template fetched for this partner and active chain.
    permitData: PermitData;
}): {
    order: PermitOrder;
    permitData: PermitData;
} {
    validatePermitData(permitData, chainId);
    const currentTimeMillis = Date.now();
    const { epoch, freshness, deadline } = validateOrderInput(orderInput, inputTokenAddress, currentTimeMillis);
    const nonce = currentTimeMillis.toString();
    const start = Math.floor(currentTimeMillis / 1000).toString();
    const order = {
        permitted: {
            token: inputTokenAddress,
            amount: orderInput.totalInputAmount,
        },
        spender: permitData.order.spender,
        nonce,
        deadline,
        witness: {
            reactor: permitData.order.witness.reactor,
            executor: permitData.order.witness.executor,
            exchange: {
                adapter: permitData.order.witness.exchange.adapter,
                ref: permitData.order.witness.exchange.ref,
                share: permitData.order.witness.exchange.share,
                data: permitData.order.witness.exchange.data,
            },
            swapper: account,
            nonce,
            start,
            deadline,
            chainid: chainId,
            exclusivity: permitData.order.witness.exclusivity,
            epoch,
            slippage: orderInput.slippageBps,
            freshness,
            input: {
                token: inputTokenAddress,
                amount: orderInput.srcAmountPerFill,
                maxAmount: orderInput.totalInputAmount,
            },
            output: {
                token: orderInput.dstToken,
                limit: orderInput.dstMinAmountPerFill,
                triggerLower: orderInput.triggerLower,
                triggerUpper: orderInput.triggerUpper,
                recipient: account,
            },
        },
    } satisfies PermitOrder;
    return { order, permitData };
}
export async function fetchDefaultPermitData(partnerId: string, chainId: number): Promise<PermitData> {
    const query = new URLSearchParams({
        partner: partnerId,
        chain: String(chainId),
    });
    const response = await fetch(`https://order-sink-v2.orbs.network/config?${query}`, {
        headers: { Accept: "application/json" },
    });
    if (!response.ok) {
        throw new Error("Failed to fetch default permit data (" + response.status + ")");
    }
    const data: unknown = await response.json();
    validatePermitData(data, chainId);
    return data;
}
function requireRecord(value: unknown): Record<string, unknown> {
    if (!value || typeof value !== "object" || Array.isArray(value)) {
        throw new Error("Invalid configuration: expected an object");
    }
    return value as Record<string, unknown>;
}
function validateAddress(value: unknown, field: string, allowZero = false): void {
    if (typeof value !== "string" || !/^0x[0-9a-fA-F]{40}$/.test(value)
        || (!allowZero && /^0x0{40}$/i.test(value))) {
        throw new Error(`${field} must be a valid ${allowZero ? "" : "non-zero "}address`);
    }
}
function validateUint32(value: unknown, field: string, max = 0xffffffff): asserts value is number {
    if (typeof value !== "number" || !Number.isInteger(value) || value < 0 || value > max) {
        throw new Error(`${field} must be an integer between 0 and ${max}`);
    }
}
function validatePermitData(value: unknown, expectedChainId: number): asserts value is PermitData {
    const data = requireRecord(value);
    const domain = requireRecord(data.domain);
    const order = requireRecord(data.order);
    const witness = requireRecord(order.witness);
    const exchange = requireRecord(witness.exchange);
    if (!Number.isSafeInteger(expectedChainId) || expectedChainId <= 0
        || domain.chainId !== expectedChainId || witness.chainid !== expectedChainId) {
        throw new Error("Configuration domain and witness chain IDs must match the connected chain");
    }
    for (const [field, address] of Object.entries({
        "domain.verifyingContract": domain.verifyingContract,
        "order.spender": order.spender,
        "witness.reactor": witness.reactor,
        "witness.executor": witness.executor,
        "exchange.adapter": exchange.adapter,
    }))
        validateAddress(address, field);
    if ((order.spender as string).toLowerCase() !== (witness.reactor as string).toLowerCase()) {
        throw new Error("Configuration spender must match the reactor");
    }
    validateAddress(exchange.ref, "exchange.ref", true);
    validateUint32(exchange.share, "exchange.share", 10000);
    validateUint32(witness.exclusivity, "witness.exclusivity");
    if (typeof exchange.data !== "string" || !/^0x(?:[0-9a-fA-F]{2})*$/.test(exchange.data)) {
        throw new Error("Configuration exchange.data must be hex bytes");
    }
    const types = requireRecord(data.types);
    const primaryFields = types.RePermitWitnessTransferFrom;
    if (typeof domain.name !== "string" || !domain.name
        || typeof domain.version !== "string" || !domain.version
