export async function fetchOrders({ account, chainId, exchange }: {
    account: Address;
    chainId: number;
    exchange: string;
}): Promise<FetchOrdersResponse> {
    if (!exchange?.trim())
        throw new Error("Exchange partner ID is required to fetch order history");
    const query = new URLSearchParams({
        swapper: account,
        chainId: String(chainId),
        exchange,
    });
    const response = await fetch(`https://order-sink-v2.orbs.network/orders?${query}`, {
        headers: { Accept: "application/json" },
    });
    if (!response.ok)
        throw new Error(`Failed to fetch orders (${response.status})`);
    return (await response.json()) as FetchOrdersResponse;
}

